using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
public static class GridShiftV22Setup {
 public static void Batch(){try{Configure();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Configure(){Directory.CreateDirectory("Docs/Validacao22");Directory.CreateDirectory("Assets/Generated/Home22");var log=new StringBuilder();
 var city=EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var cityPlayer=Object.FindFirstObjectByType<PlayerMovement>();var newScene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);var player=Object.Instantiate(cityPlayer.gameObject);player.name="Apartment player";SceneManager.MoveGameObjectToScene(player,newScene);
 foreach(var c in cityPlayer.GetComponentsInChildren<Collider>(true))log.AppendLine("City player collider "+c.name+" "+c.GetType().Name);
 foreach(var collider in city.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Collider>(true))){string n=collider.name;if(n.StartsWith("Road")||n.Contains("Cross")||n.Contains("Lane"))log.AppendLine("ROAD "+n+" "+collider.GetType().Name+" "+collider.bounds);}
 var van=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/GridShiftPlayerVan.prefab");foreach(var c in van.GetComponentsInChildren<Collider>(true))log.AppendLine("VAN "+c.name+" "+c.GetType().Name+" "+c.bounds);
 var kit=EditorSceneManager.OpenScene("Assets/Brick Project Studio/Apartment Kit/Scenes/Scene_01.unity",OpenSceneMode.Additive);var floor=kit.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).First(t=>t.name=="2nd Floor"&&t.Find("Apartment_01/Furniture")!=null);var house=Object.Instantiate(floor.gameObject);house.name="GridShift home · Apartment Kit";SceneManager.MoveGameObjectToScene(house,newScene);house.transform.position-=Vector3.up*4;var home=house.AddComponent<GridShiftApartment>();
 // Convert only copies of the kit's materials; leave the purchased originals untouched.
 var materials=new Dictionary<Material,Material>();foreach(var r in house.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(m=>{if(m==null)return m;if(materials.TryGetValue(m,out var ready))return ready;var path="Assets/Generated/Home22/"+m.name.Replace('/','_')+"-"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(m)).Substring(0,8)+".mat";var converted=AssetDatabase.LoadAssetAtPath<Material>(path);if(converted==null){converted=new Material(Shader.Find("Universal Render Pipeline/Lit"));converted.SetColor("_BaseColor",m.HasProperty("_Color")?m.GetColor("_Color"):Color.white);if(m.HasProperty("_MainTex")){converted.SetTexture("_BaseMap",m.GetTexture("_MainTex"));converted.SetTextureScale("_BaseMap",m.GetTextureScale("_MainTex"));converted.SetTextureOffset("_BaseMap",m.GetTextureOffset("_MainTex"));}if(m.HasProperty("_BumpMap")&&m.GetTexture("_BumpMap")!=null){converted.SetTexture("_BumpMap",m.GetTexture("_BumpMap"));converted.EnableKeyword("_NORMALMAP");}converted.SetFloat("_Smoothness",m.HasProperty("_Glossiness")?m.GetFloat("_Glossiness"):.3f);if(m.name.ToLowerInvariant().Contains("glass")){converted.SetFloat("_Surface",1);converted.SetFloat("_SrcBlend",5);converted.SetFloat("_DstBlend",10);converted.SetFloat("_ZWrite",0);converted.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");converted.renderQueue=3000;var color=converted.color;color.a=.2f;converted.color=color;}AssetDatabase.CreateAsset(converted,path);}materials[m]=converted;return converted;}).ToArray();}
 foreach(var legacy in house.GetComponentsInChildren<MonoBehaviour>(true))if(legacy!=null&&legacy.GetType().Namespace=="SojaExiles")legacy.enabled=false;
 foreach(var c in player.GetComponentsInChildren<CompanyEntrance>(true))Object.DestroyImmediate(c);foreach(var c in player.GetComponentsInChildren<Camera>(true)){if(c.name.ToLowerInvariant().Contains("minimap"))continue;c.farClipPlane=180;}
 EditorSceneManager.CloseScene(kit,true);EditorSceneManager.CloseScene(city,true);SceneManager.SetActiveScene(newScene);Physics.SyncTransforms();var spawn=FindStanding(house.transform,new Vector3(-3.75f,.16f,-5));home.spawn=house.transform.InverseTransformPoint(spawn);home.look=Vector3.forward;player.transform.SetPositionAndRotation(spawn,Quaternion.identity);
 var apartment=house.transform.Find("Apartment_01");var furniture=apartment.Find("Furniture");foreach(Transform t in furniture){log.AppendLine("FURNITURE "+t.name+" "+t.position);string n=t.name.ToLowerInvariant();string kind=n.Contains("bed_")?"sleep":n.Contains("shower")||n.Contains("bathtub")?"shower":n.Contains("fridge")?"fridge":n.Contains("stove")?"cook":n.Contains("toilet")?"toilet":n.Contains("vanity")||n.Contains("base_sink")?"wash":n.Contains("dresser closet")?"wardrobe":n.Contains("sofa")||n.Contains("media")?"relax":null;if(kind!=null){string title=kind=="sleep"?"Dormir · 8 horas":kind=="shower"?"Tomar banho":kind=="fridge"?"Abrir geladeira / comer":kind=="cook"?"Cozinhar refeição · 2 ingredientes":kind=="wardrobe"?"Trocar roupa / aparência":kind=="toilet"?"Usar vaso sanitário":kind=="wash"?"Lavar as mãos":"Assistir TV / descansar";var bounds=BoundsOf(t);var at=FindStanding(house.transform,new Vector3(bounds.center.x,.16f,bounds.center.z),bounds);var use=t.gameObject.AddComponent<GridShiftHomeUse>();use.kind=kind;use.title=title;use.localPoint=t.InverseTransformPoint(at);log.AppendLine("USE "+kind+" "+at);}}
 // Some furnished layouts use dressers instead of a named closet.
 if(!house.GetComponentsInChildren<GridShiftHomeUse>().Any(u=>u.kind=="wardrobe")){var dresser=furniture.Cast<Transform>().First(t=>t.name.StartsWith("Dresser"));var use=dresser.gameObject.AddComponent<GridShiftHomeUse>();use.kind="wardrobe";use.title="Trocar roupa / aparência";use.localPoint=dresser.InverseTransformPoint(FindStanding(house.transform,BoundsOf(dresser).center,BoundsOf(dresser)));}
 foreach(var light in house.GetComponentsInChildren<Light>(true)){light.enabled=true;light.intensity=Mathf.Clamp(light.intensity,1.5f,4);light.range=Mathf.Max(light.range,8);light.shadows=LightShadows.None;}
 var sun=new GameObject("Apartment daylight",typeof(Light));SceneManager.MoveGameObjectToScene(sun,newScene);sun.transform.rotation=Quaternion.Euler(50,-30,0);sun.GetComponent<Light>().type=LightType.Directional;sun.GetComponent<Light>().intensity=.6f;
 var exit=GridShiftWorldAction.Create(house.transform,"Sair de casa",home.spawn+new Vector3(0,0,-1),p=>{WorldSession.Instance.RequestTransition("SampleScene",p.transform);return true;});exit.focusOffset=Vector3.up;exit.focusSize=new Vector3(.8f,1.8f,.4f);
 RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.55f,.58f,.65f);EditorSceneManager.SaveScene(newScene,"Assets/Scenes/Apartment.unity");var list=EditorBuildSettings.scenes.Where(s=>!s.path.EndsWith("Office.unity")&&!s.path.EndsWith("Apartment.unity")).ToList();list.Add(new EditorBuildSettingsScene("Assets/Scenes/Apartment.unity",true));EditorBuildSettings.scenes=list.ToArray();AssetDatabase.SaveAssets();File.WriteAllText("Docs/Validacao22/setup.txt",log.ToString());}
 static Bounds BoundsOf(Transform t){var rs=t.GetComponentsInChildren<Renderer>();var b=new Bounds(t.position,Vector3.zero);if(rs.Length>0){b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);}return b;}
 static Vector3 FindStanding(Transform house,Vector3 near,Bounds? avoid=null){for(float radius=avoid.HasValue?.6f:0;radius<5;radius+=.3f)for(int i=0;i<24;i++){var at=near+Quaternion.Euler(0,i*15,0)*Vector3.forward*radius;at.y=2;if(!Physics.Raycast(at,Vector3.down,out var floor,3,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||!floor.transform.IsChildOf(house)||floor.normal.y<.9f||floor.point.y>.35f)continue;at=floor.point+Vector3.up*.06f;if(Physics.OverlapCapsule(at+Vector3.up*.38f,at+Vector3.up*1.5f,.32f,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore).Any())continue;return at;}throw new Exception("No reachable standing point near "+near);}
}
